package net.officefloor.hq.app.role;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.util.List;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}/roles")
@Validated
public class RoleController {

    /** What the screen shows of a role given to a user name. */
    public record RoleView(String user, String role) {
        static RoleView of(SheetRole role) {
            return new RoleView(role.getUserName(), role.getRole());
        }
    }

    /** The role form: a role of clerk, steward or viewer. */
    public record RoleForm(@NotNull @Pattern(regexp = "\\s*(clerk|steward|viewer)\\s*") String role) {
    }

    private final RoleService service;

    public RoleController(RoleService service) {
        this.service = service;
    }

    @GetMapping
    public List<RoleView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId) {
        return service.list(sheetId.trim()).stream().map(RoleView::of).toList();
    }

    @PutMapping("/{userName}")
    public RoleView set(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable @NotBlank @Size(max = 100) String userName,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody RoleForm form) {
        return RoleView.of(service.set(sheetId.trim(), user.trim(), userName.trim(), form.role().trim()));
    }
}
package net.officefloor.hq.app.role;

import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The roles user names have on a sheet: clerk (the default for any name), steward or viewer
 *  (who may change nothing). */
@Service
public class RoleService {

    private final SheetRoleRepository roles;
    private final SheetService sheets;
    private final Audit audit;

    public RoleService(SheetRoleRepository roles, SheetService sheets, Audit audit) {
        this.roles = roles;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The roles given on the sheet, by user name. */
    @Transactional(readOnly = true)
    public List<SheetRole> list(String sheetId) {
        return roles.findBySheetIdOrderByUserNameAsc(sheetId);
    }

    /** The role of a user name on the sheet: clerk unless it was given another. */
    @Transactional(readOnly = true)
    public String roleOf(String sheetId, String userName) {
        return roles.findBySheetIdAndUserName(sheetId, userName).map(SheetRole::getRole).orElse(SheetRole.CLERK);
    }

    /** Whether a user name's role on the sheet may take an action of the permission matrix (open,
     *  settle, void, reassign, close, reopen). */
    @Transactional(readOnly = true)
    public boolean may(String sheetId, String userName, String action) {
        return sheets.rolesAllowed(sheetId, action).contains(roleOf(sheetId, userName));
    }

    /** Give a user name a role on the sheet, replacing the one it had. */
    @Transactional
    public synchronized SheetRole set(String sheetId, String user, String userName, String role) {
        sheets.load(sheetId, user);
        SheetRole given = roles.findBySheetIdAndUserName(sheetId, userName)
                .orElseGet(() -> new SheetRole(sheetId, userName, role));
        given.setRole(role);
        SheetRole saved = roles.saveAndFlush(given);
        audit.recordOnCommit("ROLE_SET sheet=" + sheetId + " by=" + user + " user=" + userName + " role=" + role);
        return saved;
    }
}
package net.officefloor.hq.app.role;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/** The role a user name has on a sheet; a name with none is a clerk. A viewer may change nothing. */
@Entity
@Table(name = "sheet_role")
public class SheetRole {

    /** The role every name has until it is given another. */
    public static final String CLERK = "clerk";
    /** A steward may settle a claim of any due. */
    public static final String STEWARD = "steward";
    /** A viewer sees every screen and figure and may change nothing. */
    public static final String VIEWER = "viewer";

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "user_name", nullable = false)
    private String userName;

    @Column(name = "role", nullable = false)
    private String role;

    protected SheetRole() {
    }

    public SheetRole(String sheetId, String userName, String role) {
        this.sheetId = sheetId;
        this.userName = userName;
        this.role = role;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getUserName() {
        return userName;
    }

    public String getRole() {
        return role;
    }

    public void setRole(String role) {
        this.role = role;
    }
}
