import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Grade } from './people';
import { Session } from './session';

// The dated settings (the clerk limit, the cap, the floor, the terms and the late percent) as in force
// on the sheet's today.
export interface Settings {
  /** The most due a clerk may settle, as text with two decimals; null when there is no limit. */
  clerkLimit: string | null;
  /** The least live due a claim has, as text with two decimals. */
  floor: string;
  /** The days after its date a claim is due by. */
  terms: number;
  /** The percent of its figure an overdue claim gains for every full 30 days, as text with two decimals. */
  latePct: string;
  /** The policy date (yyyy-mm-dd); null when blank, the sheet's today then stands in. */
  policyDate: string | null;
  /** The period numbering from date (yyyy-mm-dd); null when blank (off). */
  periodNumberingFrom: string | null;
  /** The terms each grade has of its own, by grade; a grade not in it takes the sheet's terms. */
  gradeTerms: Partial<Record<Grade, number>>;
  /** The most a person's due-total comes to, as text with two decimals; null when there is no cap. */
  cap: string | null;
  /** The floors recorded, each from its from-date, earliest first. */
  floors: DatedValue[];
  /** The late percents recorded, each from its from-date, earliest first. */
  latePcts: DatedValue[];
  /** The caps recorded (null: no cap), each from its from-date, earliest first. */
  caps: DatedValue<string | null>[];
  /** The due above which a claim needs a proof before it is settled or approved, as text with two
   *  decimals; null when there is none. */
  proofThreshold: string | null;
  /** The permission matrix: for each action, the comma separated roles that may take it; blank when
   *  it keeps the standing rule. */
  permissions: Record<PermAction, string>;
  /** The grace days: when the sheet's today is changed, an open period whose to-date plus them is
   *  before it is closed; null when blank (off). */
  graceDays: number | null;
}

/** The actions the permission matrix covers. */
export type PermAction = 'open' | 'settle' | 'void' | 'reassign' | 'close' | 'reopen';

export const PERM_ACTIONS: PermAction[] = ['open', 'settle', 'void', 'reassign', 'close', 'reopen'];

/** The roles that may take each action when its entry in the matrix is blank. */
export const STANDING_PERMISSIONS: Record<PermAction, string> = {
  open: 'clerk,steward', settle: 'clerk,steward', void: 'clerk,steward', close: 'clerk,steward',
  reassign: 'steward', reopen: 'steward',
};

/** A permission entry: a comma separated list of roles (clerk, steward). */
export const PERM_ROLES = /^\s*(clerk|steward)\s*(,\s*(clerk|steward)\s*)*$/;

/** A value a dated setting takes from a date on, as text with two decimals; null when blank. */
export interface DatedValue<V extends string | null = string> {
  /** yyyy-mm-dd */
  from: string;
  value: V;
}

/** The floor a sheet starts with, in force before every from-date of its own. */
export const STARTING_FLOOR = '1.00';

/** The late percent a sheet starts with, in force before every from-date of its own. */
export const STARTING_LATE_PCT = '0.00';

/** The value of a dated setting in force on a day (yyyy-mm-dd): the one with the latest from-date on
 *  or before it, or else the starting value. */
export function valueOn<V extends string | null>(recorded: DatedValue<V>[], day: string, starting: V): V {
  let value = starting;
  for (const v of recorded) {
    if (v.from <= day) value = v.value;
  }
  return value;
}

export type RoleName = 'clerk' | 'steward' | 'viewer';

export interface Role {
  user: string;
  role: RoleName;
}

/** The roles a user name can be given; a name given none is a clerk, and a viewer may change
 *  nothing. */
export const ROLES: RoleName[] = ['clerk', 'steward', 'viewer'];

/** A limit with up to two decimals, 0.00 or more. */
export const LIMIT = /^\d{1,12}(\.\d{1,2})?$/;

/** Terms: a whole number of days, 0 or more. */
export const TERMS = /^\d{1,4}$/;

/** A policy date: yyyy-mm-dd. */
export const POLICY_DATE = /^\d{4}-\d{2}-\d{2}$/;

/** A late percent with up to two decimals, 0.00 or more. */
export const LATE_PCT = /^\d{1,5}(\.\d{1,2})?$/;

// The settings of the active sheet and the roles it gives user names.
@Injectable({ providedIn: 'root' })
export class SheetSettings {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  get(sheetId: string): Promise<Settings> {
    return firstValueFrom(this.http.get<Settings>(`${this.url(sheetId)}/settings`));
  }

  roles(sheetId: string): Promise<Role[]> {
    return firstValueFrom(this.http.get<Role[]>(`${this.url(sheetId)}/roles`));
  }

  /** Record the clerk limit (null for no limit) from a date (null for the sheet's today). */
  setClerkLimit(value: string | null, from: string | null): Promise<Settings> {
    const [sheetId, headers] = this.active();
    return firstValueFrom(this.http.put<Settings>(`${this.url(sheetId)}/settings/clerk-limit`, { value, from }, { headers }));
  }

  /** Record the cap (null for no cap) from a date (null for the sheet's today). */
  setCap(value: string | null, from: string | null): Promise<Settings> {
    const [sheetId, headers] = this.active();
    return firstValueFrom(this.http.put<Settings>(`${this.url(sheetId)}/settings/cap`, { value, from }, { headers }));
  }

  /** Record the proof threshold (null for none) from a date (null for the sheet's today). */
  setProofThreshold(value: string | null, from: string | null): Promise<Settings> {
    const [sheetId, headers] = this.active();
    return firstValueFrom(
      this.http.put<Settings>(`${this.url(sheetId)}/settings/proof-threshold`, { value, from }, { headers }),
    );
  }

  /** Record the floor from a date (null for the sheet's today). */
  setFloor(value: string, from: string | null): Promise<Settings> {
    const [sheetId, headers] = this.active();
    return firstValueFrom(this.http.put<Settings>(`${this.url(sheetId)}/settings/floor`, { value, from }, { headers }));
  }

  /** Record the terms from a date (null for the sheet's today). */
  setTerms(value: string, from: string | null): Promise<Settings> {
    const [sheetId, headers] = this.active();
    return firstValueFrom(this.http.put<Settings>(`${this.url(sheetId)}/settings/terms`, { value, from }, { headers }));
  }

  /** Record a grade's own terms from a date (null for the sheet's today). */
  setGradeTerms(grade: Grade, value: string, from: string | null): Promise<Settings> {
    const [sheetId, headers] = this.active();
    return firstValueFrom(
      this.http.put<Settings>(`${this.url(sheetId)}/settings/terms/${encodeURIComponent(grade)}`, { value, from }, { headers }),
    );
  }

  /** Record the late percent from a date (null for the sheet's today). */
  setLatePct(value: string, from: string | null): Promise<Settings> {
    const [sheetId, headers] = this.active();
    return firstValueFrom(this.http.put<Settings>(`${this.url(sheetId)}/settings/late-pct`, { value, from }, { headers }));
  }

  /** Set the policy date; null for blank (the sheet's today). */
  setPolicyDate(value: string | null): Promise<Settings> {
    const [sheetId, headers] = this.active();
    return firstValueFrom(this.http.put<Settings>(`${this.url(sheetId)}/settings/policy-date`, { value }, { headers }));
  }

  /** Set the period numbering from date; null for blank (off). */
  setPeriodNumberingFrom(value: string | null): Promise<Settings> {
    const [sheetId, headers] = this.active();
    return firstValueFrom(
      this.http.put<Settings>(`${this.url(sheetId)}/settings/period-numbering-from`, { value }, { headers }),
    );
  }

  /** Set the grace days; null for blank (off). */
  setGraceDays(value: string | null): Promise<Settings> {
    const [sheetId, headers] = this.active();
    return firstValueFrom(this.http.put<Settings>(`${this.url(sheetId)}/settings/grace-days`, { value }, { headers }));
  }

  /** Set the roles (comma separated; null for blank, the standing rule) that may take an action. */
  setPermission(action: PermAction, value: string | null): Promise<Settings> {
    const [sheetId, headers] = this.active();
    return firstValueFrom(
      this.http.put<Settings>(`${this.url(sheetId)}/settings/permissions/${action}`, { value }, { headers }),
    );
  }

  /** Give a user name a role, replacing the one it had. */
  setRole(user: string, role: RoleName): Promise<Role> {
    const [sheetId, headers] = this.active();
    return firstValueFrom(
      this.http.put<Role>(`${this.url(sheetId)}/roles/${encodeURIComponent(user)}`, { role }, { headers }),
    );
  }

  private active(): [string, { 'X-User': string }] {
    const sheetId = this.session.sheetId();
    const user = this.session.user();
    if (!sheetId || !user) throw new Error('no sheet loaded');
    return [sheetId, { 'X-User': user }];
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}`;
  }
}
import { Component, effect, inject, signal } from '@angular/core';
import { AbstractControl, FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { Session } from '../../core/session';
import { Grade } from '../../core/people';
import {
  LATE_PCT, LIMIT, PERM_ACTIONS, PERM_ROLES, POLICY_DATE, PermAction, ROLES, STANDING_PERMISSIONS, TERMS, Role, RoleName,
  SheetSettings,
} from '../../core/settings';

// The sheet's settings (the clerk limit, the cap, the proof threshold, the floor, the terms, the late percent, the policy date, period numbering from, the grace days and the permission matrix) and the roles it gives user names: clerk, the default for
// any name, steward, or viewer (who may change nothing). The settings that carry a figure are dated: each is saved from a from-date
// (blank: the sheet's today), and what shows in force is the value on the sheet's today.
@Component({
  selector: 'app-settings-form',
  imports: [ReactiveFormsModule],
  template: `
    <section aria-labelledby="settings-heading">
      <h2 id="settings-heading">Settings</h2>
      <form data-testid="settings-form" [formGroup]="settingsForm" (ngSubmit)="saveSettings()">
        <label for="setting-clerk-limit">Clerk limit</label>
        <input id="setting-clerk-limit" data-testid="setting-clerk-limit" formControlName="clerkLimit"
               inputmode="decimal" />
        <label for="setting-clerk-limit-from">Clerk limit from (blank: today)</label>
        <input id="setting-clerk-limit-from" data-testid="setting-clerk-limit-from" type="date" formControlName="clerkLimitFrom" />
        <label for="setting-cap">Cap on a person's due-total (blank: none)</label>
        <input id="setting-cap" data-testid="setting-cap" formControlName="cap" inputmode="decimal" />
        <label for="setting-cap-from">Cap from (blank: today)</label>
        <input id="setting-cap-from" data-testid="setting-cap-from" type="date" formControlName="capFrom" />
        <label for="setting-proof-threshold">Proof threshold (a claim due above it needs a proof; blank: none)</label>
        <input id="setting-proof-threshold" data-testid="setting-proof-threshold" formControlName="proofThreshold"
               inputmode="decimal" />
        <label for="setting-proof-threshold-from">Proof threshold from (blank: today)</label>
        <input id="setting-proof-threshold-from" data-testid="setting-proof-threshold-from" type="date"
               formControlName="proofThresholdFrom" />
        <label for="setting-floor">Floor</label>
        <input id="setting-floor" data-testid="setting-floor" formControlName="floor" inputmode="decimal" />
        <label for="setting-floor-from">Floor from (blank: today)</label>
        <input id="setting-floor-from" data-testid="setting-floor-from" type="date" formControlName="floorFrom" />
        <label for="setting-terms">Terms (days)</label>
        <input id="setting-terms" data-testid="setting-terms" formControlName="terms" inputmode="numeric" />
        <label for="setting-terms-from">Terms from (blank: today)</label>
        <input id="setting-terms-from" data-testid="setting-terms-from" type="date" formControlName="termsFrom" />
        <fieldset formGroupName="gradeTerms">
          <legend>Terms per grade (days; blank: the sheet's terms)</legend>
          @for (g of grades; track g) {
            <label [for]="'setting-terms-' + g">Grade {{ g }}</label>
            <input [id]="'setting-terms-' + g" [attr.data-testid]="'setting-terms-' + g" [formControlName]="g"
                   inputmode="numeric" />
            <label [for]="'setting-terms-' + g + '-from'">Grade {{ g }} terms from (blank: today)</label>
            <input [id]="'setting-terms-' + g + '-from'" [attr.data-testid]="'setting-terms-' + g + '-from'"
                   type="date" [formControlName]="g + 'From'" />
          }
        </fieldset>
        <label for="setting-late-pct">Late percent (per 30 days overdue)</label>
        <input id="setting-late-pct" data-testid="setting-late-pct" formControlName="latePct" inputmode="decimal" />
        <label for="setting-late-pct-from">Late percent from (blank: today)</label>
        <input id="setting-late-pct-from" data-testid="setting-late-pct-from" type="date" formControlName="latePctFrom" />
        <label for="setting-policy-date">Policy date (claims dated before it round half up; blank: today)</label>
        <input id="setting-policy-date" data-testid="setting-policy-date" type="date" formControlName="policyDate" />
        <label for="setting-period-numbering-from">Period numbering from (claims opened from it are numbered within their period; blank: off)</label>
        <input id="setting-period-numbering-from" data-testid="setting-period-numbering-from" type="date"
               formControlName="periodNumberingFrom" />
        <label for="setting-grace-days">Grace days (a period still open this many days after its end closes when today is changed; blank: off)</label>
        <input id="setting-grace-days" data-testid="setting-grace-days" formControlName="graceDays" inputmode="numeric" />
        <fieldset formGroupName="permissions">
          <legend>Permissions (roles that may take each action, comma separated; blank: the standing rule)</legend>
          @for (a of permActions; track a) {
            <label [for]="'setting-perm-' + a">{{ a }} (blank: {{ standing[a] }})</label>
            <input [id]="'setting-perm-' + a" [attr.data-testid]="'setting-perm-' + a" [formControlName]="a" />
          }
        </fieldset>
        <button type="submit" data-testid="settings-save">Save settings</button>
        @if (settingsError()) {
          <p role="alert" data-testid="settings-error">{{ settingsError() }}</p>
        }
      </form>
      <p>Clerk limit in force: <span data-testid="setting-clerk-limit-current">{{ clerkLimit() ?? '' }}</span></p>
      <p>Cap in force: <span data-testid="setting-cap-current">{{ cap() ?? '' }}</span></p>
      <p>Proof threshold in force: <span data-testid="setting-proof-threshold-current">{{ proofThreshold() ?? '' }}</span></p>
      <p>Floor in force: <span data-testid="setting-floor-current">{{ floor() ?? '' }}</span></p>
      <p>Terms in force: <span data-testid="setting-terms-current">{{ terms() ?? '' }}</span></p>
      @for (g of grades; track g) {
        <p>Terms in force for grade {{ g }}:
          <span [attr.data-testid]="'setting-terms-' + g + '-current'">{{ termsOf(g) ?? '' }}</span></p>
      }
      <p>Late percent in force: <span data-testid="setting-late-pct-current">{{ latePct() ?? '' }}</span></p>
      <p>Policy date in force: <span data-testid="setting-policy-date-current">{{ policyDate() ?? '' }}</span></p>
      <p>Period numbering from: <span data-testid="setting-period-numbering-from-current">{{ periodNumberingFrom() ?? '' }}</span></p>
      <p>Grace days: <span data-testid="setting-grace-days-current">{{ graceDays() ?? '' }}</span></p>
      @for (a of permActions; track a) {
        <p>Roles that may {{ a }}:
          <span [attr.data-testid]="'setting-perm-' + a + '-current'">{{ permissions()[a] ?? '' }}</span></p>
      }
      <h3>Roles</h3>
      <form data-testid="role-form" [formGroup]="roleForm" (ngSubmit)="saveRole()">
        <label for="role-form-user">User</label>
        <input id="role-form-user" data-testid="role-form-user" formControlName="user" />
        <label for="role-form-role">Role</label>
        <input id="role-form-role" data-testid="role-form-role" formControlName="role" list="role-names" />
        <datalist id="role-names">
          @for (r of roleNames; track r) {
            <option [value]="r"></option>
          }
        </datalist>
        <button type="submit" data-testid="role-form-submit">Set role</button>
        @if (roleError()) {
          <p role="alert" data-testid="role-form-error">{{ roleError() }}</p>
        }
      </form>
      <table data-testid="roles">
        <caption>Roles given (any other name is a clerk)</caption>
        <thead>
          <tr><th scope="col">User</th><th scope="col">Role</th></tr>
        </thead>
        <tbody>
          @for (r of roles(); track r.user) {
            <tr [attr.data-testid]="'role-row-' + r.user">
              <th scope="row" data-testid="role-user">{{ r.user }}</th>
              <td data-testid="role-value">{{ r.role }}</td>
            </tr>
          }
        </tbody>
      </table>
    </section>
  `,
})
export class SettingsForm {
  private readonly api = inject(SheetSettings);
  private readonly session = inject(Session);

  protected readonly roleNames = ROLES;
  protected readonly clerkLimit = signal<string | null>(null);
  protected readonly cap = signal<string | null>(null);
  protected readonly proofThreshold = signal<string | null>(null);
  protected readonly floor = signal<string | null>(null);
  protected readonly terms = signal<number | null>(null);
  protected readonly grades: Grade[] = ['A', 'B', 'C'];
  /** The terms each grade has of its own; a grade not in it takes the sheet's terms. */
  protected readonly gradeTerms = signal<Partial<Record<Grade, number>>>({});
  protected readonly latePct = signal<string | null>(null);
  protected readonly policyDate = signal<string | null>(null);
  protected readonly periodNumberingFrom = signal<string | null>(null);
  protected readonly graceDays = signal<number | null>(null);
  protected readonly permActions = PERM_ACTIONS;
  protected readonly standing = STANDING_PERMISSIONS;
  /** The permission matrix as set; an action's entry is blank when it keeps the standing rule. */
  protected readonly permissions = signal<Partial<Record<PermAction, string>>>({});
  protected readonly roles = signal<Role[]>([]);
  protected readonly settingsError = signal('');
  protected readonly roleError = signal('');
  /** Whether a submit is waiting for its answer: a second submit meanwhile is ignored. */
  private submitting = false;
  /** Only the newest read of the sheet may show: a load overtaken by another is dropped. */
  private reads = 0;
  protected readonly settingsForm = new FormGroup({
    clerkLimit: new FormControl('', { nonNullable: true }),
    clerkLimitFrom: new FormControl('', { nonNullable: true }),
    cap: new FormControl('', { nonNullable: true }),
    capFrom: new FormControl('', { nonNullable: true }),
    proofThreshold: new FormControl('', { nonNullable: true }),
